{"title":"Observed price vs historical baseline","type":"vega","params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {"type": "fit", "contains": "padding"},
  "padding": {"left": 56, "right": 12, "top": 26, "bottom": 34},
  "data": [{
    "name": "prices",
    "url": {"%context%": true, "%timefield%": "event_time", "index": "agrishock-market-shock-signals-*", "body": {"size": 1, "_source": ["observed_price", "baseline_price"]}},
    "format": {"property": "hits.hits"},
    "transform": [
      {"type": "formula", "as": "historical_median", "expr": "datum._source.baseline_price"},
      {"type": "formula", "as": "observed_price", "expr": "datum._source.observed_price"},
      {"type": "fold", "fields": ["historical_median", "observed_price"], "as": ["series", "value"]},
      {"type": "formula", "as": "label", "expr": "datum.series === 'historical_median' ? 'Historical median' : 'Observed price'"}
    ]
  }],
  "scales": [
    {"name": "x", "type": "band", "domain": {"data": "prices", "field": "label"}, "range": "width", "padding": 0.32},
    {"name": "y", "type": "linear", "domain": {"data": "prices", "field": "value"}, "range": "height", "nice": true, "zero": true},
    {"name": "color", "type": "ordinal", "domain": ["Historical median", "Observed price"], "range": ["#6B7B8C", "#00BFB3"]}
  ],
  "axes": [
    {"orient": "bottom", "scale": "x", "labelColor": "#A7B1C2", "labelFontSize": 12, "labelPadding": 10, "tickSize": 0, "domainColor": "#3B4656"},
    {"orient": "left", "scale": "y", "title": "Rs./Quintal", "titleColor": "#A7B1C2", "labelColor": "#A7B1C2", "grid": true, "gridColor": "#263241", "tickColor": "#3B4656", "domain": false}
  ],
  "marks": [
    {"type": "rect", "from": {"data": "prices"}, "encode": {"update": {"x": {"scale": "x", "field": "label"}, "width": {"scale": "x", "band": 1}, "y": {"scale": "y", "field": "value"}, "y2": {"scale": "y", "value": 0}, "fill": {"scale": "color", "field": "label"}, "cornerRadiusTopLeft": {"value": 5}, "cornerRadiusTopRight": {"value": 5}, "tooltip": {"signal": "{\"Series\": datum.label, \"Rs./Quintal\": format(datum.value, ',')}"}}}},
    {"type": "text", "from": {"data": "prices"}, "encode": {"update": {"x": {"scale": "x", "field": "label", "band": 0.5}, "y": {"scale": "y", "field": "value", "offset": -8}, "text": {"signal": "'₹' + format(datum.value, ',')"}, "fill": {"value": "#E6EDF5"}, "fontSize": {"value": 16}, "fontWeight": {"value": 700}, "align": {"value": "center"}}}}
  ]
}"},"aggs":[]}
